css:
.tmtsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1a2436;
    background: linear-gradient(165deg, #eef1f6 0%, #e4e9f2 100%);
    border-radius: 18px;
}

.tmtsim-container * {
    box-sizing: border-box;
}

.tmtsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11203b 0%, #1c3a63 55%, #284e85 100%);
    color: #f3f6fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 32, 59, 0.32);
    border-bottom: 4px solid #c8a44d;
}

.tmtsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.tmtsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7d3a0;
    background: rgba(200, 164, 77, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.tmtsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dde6f3;
}

.tmtsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #233655;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.tmtsim-period-counter #currentDay,
.tmtsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #11203b;
}

.tmtsim-round-name {
    background: #d4ddec;
    color: #11203b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.tmtsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5a12;
    background: #f7e9cf;
    padding: 4px 12px;
    border-radius: 999px;
}

.tmtsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.tmtsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6deec;
    box-shadow: 0 4px 14px rgba(17, 32, 59, 0.06);
    border-top: 4px solid #284e85;
}

.tmtsim-card-diversity { border-top-color: #2f6fb0; }
.tmtsim-card-cohesion { border-top-color: #1f8a6d; }
.tmtsim-card-readiness { border-top-color: #c8a44d; }
.tmtsim-card-roi { border-top-color: #11203b; }

.tmtsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5c6c87;
}

.tmtsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11203b;
}

.tmtsim-card-diversity .tmtsim-value { color: #2f6fb0; }
.tmtsim-card-cohesion .tmtsim-value { color: #1f8a6d; }
.tmtsim-card-readiness .tmtsim-value { color: #9a7a22; }
.tmtsim-card-roi .tmtsim-value { font-size: 1.9rem; color: #11203b; }

.tmtsim-sublabel {
    font-size: 0.75rem;
    color: #71819b;
    line-height: 1.35;
}

.tmtsim-card-cohesion.tmtsim-cohesion-fractured .tmtsim-value { color: #c0392b; }
.tmtsim-card-roi.tmtsim-roi-target .tmtsim-value { color: #1f8a6d; }
.tmtsim-card-roi.tmtsim-roi-miss .tmtsim-value { color: #c0392b; }

.tmtsim-resource-bar {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-bottom: 18px;
}

.tmtsim-resource {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11203b;
    color: #eaf0fa;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.92rem;
}

.tmtsim-resource #budgetDisplay,
.tmtsim-resource #seatsDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7d3a0;
}

.tmtsim-resource.tmtsim-over #budgetDisplay,
.tmtsim-resource.tmtsim-over #seatsDisplay {
    color: #ff9a8a;
}

.tmtsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c8a44d;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 32, 59, 0.05);
}

.tmtsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.tmtsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11203b;
    margin-bottom: 6px;
}

.tmtsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3c58;
}

.tmtsim-briefing-text strong { color: #1f6f8f; }
.tmtsim-briefing-text em { color: #9a5a12; font-style: italic; }

.tmtsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6deec;
    box-shadow: 0 4px 14px rgba(17, 32, 59, 0.06);
}

.tmtsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11203b;
    border-bottom: 2px solid #e4e9f2;
    padding-bottom: 8px;
}

.tmtsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #233655;
    margin: 14px 0 6px;
}

.tmtsim-container select,
.tmtsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b6c4dc;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f9fd;
    color: #1a2436;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.tmtsim-container select:focus,
.tmtsim-container input[type="number"]:focus {
    outline: none;
    border-color: #284e85;
    box-shadow: 0 0 0 3px rgba(40, 78, 133, 0.16);
}

.tmtsim-container select option {
    background-color: #ffffff;
    color: #1a2436;
}

.tmtsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #284e85;
}

.tmtsim-range-readout,
.tmtsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1c3a63;
    margin-top: 4px;
}

.tmtsim-range-readout span:last-child {
    color: #1f8a6d;
    font-weight: 800;
}

.tmtsim-alloc-readout {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 16px;
    align-items: center;
    background: #f1f5fb;
    border: 1px solid #d6e0ee;
    border-radius: 9px;
    padding: 8px 12px;
    margin-top: 8px;
}

.tmtsim-alloc-readout #addedReadout,
.tmtsim-alloc-readout #costReadout {
    color: #1f8a6d;
    font-weight: 800;
}

.tmtsim-alloc-cost {
    margin-left: auto;
}

.tmtsim-hint {
    font-size: 0.8rem;
    color: #71819b;
    margin-top: 4px;
    line-height: 1.4;
}

.tmtsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.tmtsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f4f7fc;
    border: 1px solid #dbe4f0;
    border-radius: 9px;
    padding: 8px 12px;
}

.tmtsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #233655;
}

.tmtsim-alloc-row input[type="number"] {
    width: 84px;
    flex: 0 0 84px;
}

.tmtsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.tmtsim-container .btn-primary {
    background: linear-gradient(135deg, #1c3a63 0%, #284e85 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(28, 58, 99, 0.30);
}

.tmtsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.tmtsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b6c4dc;
    color: #5c6c87;
}

.tmtsim-coach {
    background: #11203b;
    color: #eaf0fa;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 32, 59, 0.24);
    border-left: 4px solid #c8a44d;
}

.tmtsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7d3a0;
    margin-bottom: 8px;
}

.tmtsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.tmtsim-coach-body strong { color: #f0d693; }
.tmtsim-coach-body em { color: #9fd8c4; font-style: italic; }

.tmtsim-history,
.tmtsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6deec;
    box-shadow: 0 4px 14px rgba(17, 32, 59, 0.06);
}

.tmtsim-history h3,
.tmtsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11203b;
}

.tmtsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #233655;
}

.tmtsim-container table#usfHistoryTable th {
    background: #eaeff7;
    color: #11203b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d2dded;
}

.tmtsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f8;
}

.tmtsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7faff;
}

.tmtsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .tmtsim-container {
        padding: 14px;
    }
    .tmtsim-header h1 {
        font-size: 1.7rem;
    }
    .tmtsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .tmtsim-value {
        font-size: 2rem;
    }
    .tmtsim-card-roi .tmtsim-value {
        font-size: 1.6rem;
    }
    .tmtsim-clock {
        margin-left: 0;
    }
    .tmtsim-period-counter {
        font-size: 0.88rem;
    }
    .tmtsim-resource-bar {
        grid-template-columns: 1fr;
    }
    .tmtsim-alloc-readout {
        flex-direction: column;
        align-items: flex-start;
    }
    .tmtsim-alloc-cost {
        margin-left: 0;
    }
    .tmtsim-alloc-row {
        flex-wrap: wrap;
    }
    .tmtsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .tmtsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme) ---- */
.tmtsim-completion { padding: 8px 4px 4px; }
.tmtsim-cm-head { text-align: center; margin-bottom: 16px; }
.tmtsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #284e85; }
.tmtsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5b7bb0; }
.tmtsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #11203b; }
.tmtsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.tmtsim-cm-yes { background: rgba(31,138,109,0.14); color: #1a7059; border: 1px solid rgba(31,138,109,0.5); }
.tmtsim-cm-no { background: rgba(192,57,43,0.12); color: #b23325; border: 1px solid rgba(192,57,43,0.45); }
.tmtsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.tmtsim-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(40,78,133,0.08); border: 1px solid rgba(40,78,133,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.tmtsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #284e85; }
.tmtsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.tmtsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #11203b; }
.tmtsim-cm-insights { margin: 0; padding-left: 20px; }
.tmtsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

