(function() {
    'use strict';

    class TMTAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Building the Global TMT`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Helvetia Precision Group · Horizon Asia).
            this.START_SEATS = 9;            // current executive committee
            this.SEAT_CAP = 12;              // headcount cap
            this.MAX_ADDED = 3;              // 12 - 9
            this.BUDGET_CAP = 18;            // CHF 18M / year (in CHF millions)
            this.COST_ASIA = 1.4;           // external Asia hire, fully loaded
            this.COST_RELOCATE = 0.6;        // internal relocation to Asia
            this.COST_PROMOTE = 0.3;         // internal promotion
            this.START_APAC = 230;           // CHF 230M current APAC revenue
            this.APAC_TARGET = 690;          // CHF 690M Horizon Asia target

            // Starting KPI seeds (homogeneous = cohesive but undiverse and unready).
            this.START_DIVERSITY = 12;
            this.START_COHESION = 82;
            this.START_READINESS = 18;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    diversity: this.START_DIVERSITY,
                    cohesion: this.START_COHESION,
                    readiness: this.START_READINESS,
                    apac: this.START_APAC,
                    seats: this.START_SEATS,
                    seatsAdded: 0,
                    budgetUsed: 0,
                    overCap: false,
                    fractured: false,
                    targetMissed: false,
                    asiaTot: 0,
                    relocTot: 0,
                    promoTot: 0,
                    continuity: 50,
                    reshuffled: false,
                    exec: 1,
                    diversityHistory: [this.START_DIVERSITY],
                    cohesionHistory: [this.START_COHESION],
                    readinessHistory: [this.START_READINESS],
                    apacHistory: [this.START_APAC],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    gap: `capability`,
                    profile: `targeted`,
                    nonneg: `localops`,
                    urgency: 60,
                    asiaHires: 2,
                    relocate: 1,
                    promote: 0,
                    continuity: 55,
                    speed: `balanced`,
                    sequence: `two`,
                    match: `profile`,
                    integration: 3,
                    pace: 60,
                    diagnose: `right`,
                    recalibrate: `integrate`,
                    board: `revenue`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gap = document.getElementById(`gapInput`);
                const profile = document.getElementById(`profileInput`);
                const nonneg = document.getElementById(`nonnegInput`);
                const urg = document.getElementById(`urgencyInput`);
                if (gap) decisions.gap = gap.value;
                if (profile) decisions.profile = profile.value;
                if (nonneg) decisions.nonneg = nonneg.value;
                if (urg) decisions.urgency = parseInt(urg.value, 10);
                if (!Number.isFinite(decisions.urgency) || decisions.urgency < 0 || decisions.urgency > 100) {
                    warn(`warn_urgency_range`); return false;
                }
            } else if (round === 2) {
                const ah = document.getElementById(`asiaHiresInput`);
                const rl = document.getElementById(`relocateInput`);
                const pr = document.getElementById(`promoteInput`);
                const cont = document.getElementById(`continuityInput`);
                const sp = document.getElementById(`speedInput`);
                if (ah) decisions.asiaHires = parseInt(ah.value, 10);
                if (rl) decisions.relocate = parseInt(rl.value, 10);
                if (pr) decisions.promote = parseInt(pr.value, 10);
                if (cont) decisions.continuity = parseInt(cont.value, 10);
                if (sp) decisions.speed = sp.value;
                const counts = [decisions.asiaHires, decisions.relocate, decisions.promote];
                if (counts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_appoint_negative`); return false;
                }
                const added = decisions.asiaHires + decisions.relocate + decisions.promote;
                if (added < 1) {
                    warn(`warn_appoint_zero`); return false;
                }
                if (added > this.MAX_ADDED) {
                    warn(`warn_seat_cap`); return false;
                }
                const cost = decisions.asiaHires * this.COST_ASIA + decisions.relocate * this.COST_RELOCATE + decisions.promote * this.COST_PROMOTE;
                if (cost > this.BUDGET_CAP + 0.001) {
                    warn(`warn_budget_cap`); return false;
                }
                if (!Number.isFinite(decisions.continuity) || decisions.continuity < 0 || decisions.continuity > 100) {
                    warn(`warn_continuity_range`); return false;
                }
            } else if (round === 3) {
                const seq = document.getElementById(`sequenceInput`);
                const mt = document.getElementById(`matchInput`);
                const ig = document.getElementById(`integrationInput`);
                const pc = document.getElementById(`paceInput`);
                if (seq) decisions.sequence = seq.value;
                if (mt) decisions.match = mt.value;
                if (ig) decisions.integration = parseFloat(ig.value);
                if (pc) decisions.pace = parseInt(pc.value, 10);
                if (!Number.isFinite(decisions.integration) || decisions.integration < 0) {
                    warn(`warn_integration_negative`); return false;
                }
                const remaining = this.BUDGET_CAP - state.domainState.budgetUsed;
                if (decisions.integration > remaining + 0.001) {
                    warn(`warn_integration_budget`); return false;
                }
                if (!Number.isFinite(decisions.pace) || decisions.pace < 0 || decisions.pace > 100) {
                    warn(`warn_pace_range`); return false;
                }
            } else if (round === 4) {
                const dg = document.getElementById(`diagnoseInput`);
                const rc = document.getElementById(`recalibrateInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (dg) decisions.diagnose = dg.value;
                if (rc) decisions.recalibrate = rc.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas applied to the four KPIs this round. Headroom is preserved so that
            // every wrong lever still registers on the final scorecard.
            let divDelta = 0, cohDelta = 0, readyDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the team-strategy gap. The real gap is a CAPABILITY gap
                // (zero Asia experience), not effort, structure, or outsourceable.
                if (d.gap === `capability`) {
                    readyDelta += 10; coachKey = `coach_r1_capability`;
                } else if (d.gap === `structure`) {
                    readyDelta += 1; coachKey = `coach_r1_structure`;
                } else if (d.gap === `effort`) {
                    readyDelta -= 6; cohDelta -= 2; coachKey = `coach_r1_effort`;
                } else { // consultants
                    readyDelta -= 8; coachKey = `coach_r1_consultants`;
                }

                // Target profile: TARGETED (add the right diversity, keep a continuity core)
                // beats both the cohesion trap (minimal) and diversity overload (maximal).
                if (d.profile === `targeted`) {
                    readyDelta += 8; coachKey = (d.gap === `capability`) ? `coach_r1_diag_sharp` : coachKey;
                } else if (d.profile === `minimal`) {
                    readyDelta -= 6; coachKey = `coach_r1_minimal`;
                } else { // maximal
                    readyDelta -= 2; cohDelta -= 2; coachKey = `coach_r1_maximal`;
                }

                // Non-negotiable capability: real Asia operating experience.
                if (d.nonneg === `localops`) { readyDelta += 6; }
                else if (d.nonneg === `precision`) { readyDelta -= 4; }
                else { readyDelta -= 5; coachKey = (coachKey === `coach_default`) ? `coach_r1_swiss` : coachKey; }

                // Urgency: candour that the current TMT cannot execute.
                if (d.urgency >= 60) { readyDelta += 5; }
                else if (d.urgency <= 25) { readyDelta -= 6; coachKey = `coach_r1_lowurgency`; }

                summaryKey = (d.gap === `capability` && d.profile === `targeted` && d.nonneg === `localops`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Staff the top team. This is the core round and the main diversity driver.
                const asia = d.asiaHires, reloc = d.relocate, promo = d.promote;
                const added = asia + reloc + promo;
                spend = asia * this.COST_ASIA + reloc * this.COST_RELOCATE + promo * this.COST_PROMOTE;

                ds.seatsAdded = added;
                ds.seats = this.START_SEATS + added;

                // Persist the slate so the end-of-round capability mapping can judge whether the
                // diversity actually CONVERTS to Asia capability (it needs a protected continuity
                // core and a measured number of strangers — see the coreFactor below).
                ds.asiaTot = asia;
                ds.relocTot = reloc;
                ds.promoTot = promo;
                ds.continuity = d.continuity;

                // Diversity rises mainly with external Asia hires of varied nationalities;
                // relocations add some Asia experience but no nationality diversity;
                // pure internal promotion adds none.
                divDelta += asia * 19 + reloc * 8 + promo * 0;

                // Cohesion: each external hire is a stranger (faultline risk); relocations are
                // known quantities; protecting a European continuity core preserves cohesion.
                cohDelta -= asia * 8;
                cohDelta -= reloc * 1;
                cohDelta += promo * 2;

                // European continuity: a deliberate cohesive core. Mid-high is best — too low
                // (replace-everyone) crushes cohesion, too high (keep-everyone) starves Asia
                // capability. Reward the band; penalise the extremes.
                if (d.continuity >= 40 && d.continuity <= 70) {
                    cohDelta += 5; readyDelta += 3;
                } else if (d.continuity > 70) {
                    cohDelta += 3; divDelta -= 8; readyDelta -= 2;
                } else { // < 40 — almost no continuity core
                    cohDelta -= 8; readyDelta -= 2;
                }

                // Readiness from genuine Asia capability brought onto the committee.
                readyDelta += asia * 6 + reloc * 4;

                // Speed vs fit when hiring externally.
                if (asia >= 1) {
                    switch (d.speed) {
                        case `balanced`: cohDelta += 6; readyDelta += 4; break;
                        case `speed`: cohDelta -= 8; readyDelta += 2; coachKey = `coach_r2_speed`; break;
                        case `fit`: divDelta -= 7; readyDelta -= 5; coachKey = `coach_r2_fit`; break;
                    }
                }

                // Diagnose the staffing archetype for the coach message.
                if (asia === 0 && reloc <= 1) {
                    coachKey = `coach_r2_cohesiontrap`;
                    summaryKey = `sum_r2_cohesion`;
                } else if (asia >= 3 || (added >= this.MAX_ADDED && asia >= 2 && d.continuity < 40)) {
                    coachKey = `coach_r2_overload`;
                    summaryKey = `sum_r2_overload`;
                } else if (asia >= 1 && asia <= 2 && (reloc + promo) >= 1 && d.continuity >= 40 && d.continuity <= 70 && d.speed === `balanced`) {
                    coachKey = `coach_r2_balanced`;
                    summaryKey = `sum_r2_good`;
                } else {
                    coachKey = (coachKey === `coach_default`) ? `coach_r2_mixed` : coachKey;
                    summaryKey = `sum_r2_weak`;
                }
            } else if (round === 3) {
                // Sequence the entries to the team and invest in integration.
                // Sequencing: two-first matches a newly built team and the 12-month clock.
                // Sequence/match/integration also feed a persistent EXECUTION factor (ds.exec)
                // that multiplies realised APAC revenue directly — so these levers register on
                // the final scorecard even when the cohesion/readiness meters are near their cap.
                switch (d.sequence) {
                    case `two`: readyDelta += 14; ds.exec *= 1.00; coachKey = `coach_r3_two`; break;
                    case `one`: readyDelta += 2; ds.exec *= 0.86; coachKey = `coach_r3_one`; break;
                    case `all`: readyDelta -= 12; cohDelta -= 5; ds.exec *= 0.72; coachKey = `coach_r3_all`; break;
                }

                // Matching leads to markets: profile-to-market wins; seniority ignores Asia
                // experience; concentrating all entries on one hire is a single point of failure.
                switch (d.match) {
                    case `profile`: readyDelta += 8; cohDelta += 2; ds.exec *= 1.00; coachKey = (d.sequence === `two`) ? `coach_r3_matched` : coachKey; break;
                    case `seniority`: readyDelta -= 7; ds.exec *= 0.85; coachKey = `coach_r3_seniority`; break;
                    case `single`: readyDelta -= 4; cohDelta -= 2; ds.exec *= 0.90; coachKey = `coach_r3_single`; break;
                }

                // Integration spend: the engine that turns diversity into cohesion. Repairs the
                // faultlines created by external hiring in Round 2.
                spend += d.integration;
                if (d.integration >= 2.5) { cohDelta += 10; readyDelta += 5; ds.exec *= 1.00; }
                else if (d.integration >= 1) { cohDelta += 5; readyDelta += 2; ds.exec *= 0.90; }
                else { cohDelta -= 8; ds.exec *= 0.74; coachKey = `coach_r3_nointegration`; }

                // Decision-speed discipline protects cohesion during integration.
                if (d.pace >= 60) { cohDelta += 4; readyDelta += 2; }
                else if (d.pace <= 25) { cohDelta -= 6; readyDelta -= 2; ds.exec *= 0.94; }

                summaryKey = (d.sequence === `two` && d.match === `profile` && d.integration >= 2.5) ? `sum_r3_good` :
                    (d.sequence === `all` ? `sum_r3_overreach` : (d.integration < 1 ? `sum_r3_neglect` : `sum_r3_weak`));
            } else if (round === 4) {
                // Read the results and defend the design. This round mostly judges and
                // recalibrates; it nudges KPIs modestly so it cannot rescue a broken team.
                if (d.diagnose === `right`) {
                    readyDelta += 5; cohDelta += 3; coachKey = `coach_r4_right`;
                } else if (d.diagnose === `toolittle`) {
                    coachKey = `coach_r4_toolittle`;
                } else { // toomuch
                    coachKey = `coach_r4_toomuch`;
                }

                switch (d.recalibrate) {
                    case `integrate`: cohDelta += 5; readyDelta += 5; break;
                    case `freeze`: cohDelta += 2; readyDelta -= 2; ds.exec *= 0.96; coachKey = `coach_r4_freeze`; break;
                    case `reshuffle`: cohDelta -= 12; readyDelta -= 4; ds.reshuffled = true; ds.exec *= 0.88; coachKey = `coach_r4_reshuffle`; break;
                }

                // The board's challenge: design must serve expansion performance, not the index.
                switch (d.board) {
                    case `revenue`: readyDelta += 8; cohDelta += 4; coachKey = (d.recalibrate === `integrate`) ? `coach_r4_revenue` : coachKey; break;
                    case `index`: readyDelta -= 6; ds.exec *= 0.92; coachKey = `coach_r4_index`; break;
                    case `harmony`: divDelta -= 4; readyDelta -= 6; ds.exec *= 0.94; coachKey = `coach_r4_harmony`; break;
                }

                readyDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.diagnose === `right` && d.board === `revenue` && d.recalibrate === `integrate`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;
            ds.overCap = ds.seatsAdded > this.MAX_ADDED || ds.budgetUsed > this.BUDGET_CAP + 0.001;

            // Apply deltas with 0–100 bounds.
            ds.diversity = Math.max(0, Math.min(100, ds.diversity + divDelta));
            ds.cohesion = Math.max(0, Math.min(100, ds.cohesion + cohDelta));
            ds.readiness = Math.max(0, Math.min(100, ds.readiness + readyDelta));

            // Cohesion fracture flag (diversity overload signature).
            if (ds.cohesion < 45) ds.fractured = true;

            // Expansion ROI: realised APAC revenue is driven by the INTERACTION of diversity
            // (local market knowledge), cohesion (ability to execute) and entry readiness
            // (sequencing + integration). A high index with collapsed cohesion does NOT convert;
            // a cohesive team with no diversity has no Asia knowledge to deploy. This is the
            // boundary condition that punishes both the cohesion trap and diversity overload.

            // coreFactor: how much of the raw diversity actually CONVERTS to Asia capability.
            // "Add the right diversity, not the most" — replacing everyone (no continuity core)
            // or over-hiring strangers (3 external at once) inflates the index but leaves the
            // diversity un-anchored, so it does not become execution. This is what makes the
            // measured, core-protected slate strictly out-perform diversity-overload even after
            // a strong Round-3 integration recovery.
            let coreFactor = 1;
            if (ds.continuity < 40) coreFactor -= 0.30;
            else if (ds.continuity > 70) coreFactor -= 0.10;
            if (ds.asiaTot >= 3) coreFactor -= 0.25;
            if ((ds.relocTot + ds.promoTot) === 0 && ds.asiaTot >= 2) coreFactor -= 0.12;
            if (ds.reshuffled) coreFactor -= 0.10;
            coreFactor = Math.max(0.35, coreFactor);
            const convertingDiv = ds.diversity * coreFactor;

            const divF = convertingDiv / 100;
            const cohF = ds.cohesion / 100;
            const readyF = ds.readiness / 100;
            // Balanced capability: penalised when (converting) diversity and cohesion are far apart.
            const balance = 1 - Math.abs(divF - cohF) * 0.6;
            // ds.exec carries the sequencing + integration + lead-matching quality directly into
            // realised revenue, so those levers register even when the index meters near the cap.
            const capability = Math.pow(divF * cohF, 0.40) * balance * readyF * ds.exec * 1.66;
            // Map capability (0..1) onto the APAC revenue range CHF 230M -> 690M. The balanced,
            // core-protected, two-first, profile-matched, well-integrated strategy reaches the
            // CHF 690M target; every classic error falls measurably short of it.
            ds.apac = Math.round(this.START_APAC + (this.APAC_TARGET - this.START_APAC) * Math.max(0, Math.min(1, capability)));

            ds.diversityHistory.push(Math.round(ds.diversity));
            ds.cohesionHistory.push(Math.round(ds.cohesion));
            ds.readinessHistory.push(Math.round(ds.readiness));
            ds.apacHistory.push(ds.apac);

            if (round === this.ROUNDS.length && ds.apac < this.APAC_TARGET) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                diversity: Math.round(ds.diversity),
                diversityDelta: Math.round(divDelta),
                cohesion: Math.round(ds.cohesion),
                cohesionDelta: Math.round(cohDelta),
                readiness: Math.round(ds.readiness),
                readinessDelta: Math.round(readyDelta),
                apac: ds.apac,
                seats: ds.seats,
                budgetUsed: ds.budgetUsed,
                fractured: ds.fractured,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`diversityDisplay`, `domainState.diversity`, (v) => Math.round(Number(v)));
            uiManager.bind(`cohesionDisplay`, `domainState.cohesion`, (v) => {
                const card = document.querySelector(`.tmtsim-card-cohesion`);
                if (card) card.classList.toggle(`tmtsim-cohesion-fractured`, Number(v) < 45);
                return Math.round(Number(v));
            });
            uiManager.bind(`readinessDisplay`, `domainState.readiness`, (v) => Math.round(Number(v)));
            uiManager.bind(`roiDisplay`, `domainState.apac`, (v) => {
                const card = document.querySelector(`.tmtsim-card-roi`);
                if (card) {
                    card.classList.toggle(`tmtsim-roi-target`, Number(v) >= this.APAC_TARGET);
                    card.classList.toggle(`tmtsim-roi-miss`, Number(v) < this.APAC_TARGET);
                }
                return `CHF ` + Math.round(Number(v)) + `M`;
            });

            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const res = document.querySelectorAll(`.tmtsim-resource`)[0];
                if (res) res.classList.toggle(`tmtsim-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return `CHF ` + Number(v).toFixed(1) + `M / CHF 18M`;
            });
            uiManager.bind(`seatsDisplay`, `domainState.seats`, (v) => {
                const res = document.querySelectorAll(`.tmtsim-resource`)[1];
                if (res) res.classList.toggle(`tmtsim-over`, Number(v) > this.SEAT_CAP);
                return Math.round(Number(v)) + ` / 12`;
            });

            const self = this;

            // Urgency slider readout.
            const urg = document.getElementById(`urgencyInput`);
            const urgReadout = document.getElementById(`urgencyReadout`);
            if (urg && urgReadout) {
                urgReadout.textContent = urg.value;
                urg.addEventListener(`input`, function() { urgReadout.textContent = urg.value; });
            }

            // Continuity slider readout.
            const cont = document.getElementById(`continuityInput`);
            const contReadout = document.getElementById(`continuityReadout`);
            if (cont && contReadout) {
                contReadout.textContent = cont.value;
                cont.addEventListener(`input`, function() { contReadout.textContent = cont.value; });
            }

            // Pace slider readout.
            const pc = document.getElementById(`paceInput`);
            const pcReadout = document.getElementById(`paceReadout`);
            if (pc && pcReadout) {
                pcReadout.textContent = pc.value;
                pc.addEventListener(`input`, function() { pcReadout.textContent = pc.value; });
            }

            // Round-2 appointment live totals (seats added + cost).
            const apptIds = [`asiaHiresInput`, `relocateInput`, `promoteInput`];
            const addedReadout = document.getElementById(`addedReadout`);
            const costReadout = document.getElementById(`costReadout`);
            const recompute = function() {
                const asia = parseInt((document.getElementById(`asiaHiresInput`) || {}).value, 10) || 0;
                const reloc = parseInt((document.getElementById(`relocateInput`) || {}).value, 10) || 0;
                const promo = parseInt((document.getElementById(`promoteInput`) || {}).value, 10) || 0;
                const added = asia + reloc + promo;
                const cost = asia * self.COST_ASIA + reloc * self.COST_RELOCATE + promo * self.COST_PROMOTE;
                if (addedReadout) addedReadout.textContent = added;
                if (costReadout) costReadout.textContent = `CHF ` + (Math.round(cost * 10) / 10).toFixed(1) + `M`;
                const bar = document.querySelector(`.tmtsim-alloc-readout`);
                if (bar) bar.style.color = (added > self.MAX_ADDED || cost > self.BUDGET_CAP + 0.001) ? `#c0392b` : ``;
            };
            apptIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
                tmtChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_diversity`, `TMT Diversity Index`),
