                                data: [],
                                borderColor: `#11203b`,
                                backgroundColor: `rgba(17,32,59,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#11203b`,
                                yAxisID: `y1`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
